function maxWeightedSubsequence(A, k){
  const n = A.length; // 1-indexed in problem
  const dp = Array.from({length:k+1}, ()=> Array(n+1).fill(-Infinity));
  for(let i=0;i<=n;i++) dp[0][i]=0;
  for(let t=1;t<=k;t++){
    for(let i=1;i<=n;i++){
      dp[t][i] = Math.max(dp[t][i-1], dp[t-1][i-1] + t*A[i-1]);
    }
  }
  // backtrack omitted for brevity
  return {value: dp[k][n]};
}
